export type GeneratedQuestion = { id: string; prompt: string; answers: string[]; correct: number; explain: string; domain?:string; skill?:string; difficulty?:string; templateId?:string; templateVersion?:number; seed?:number; params?:Record<string,number|string>;context?:string;responseType?:"multiple-choice"|"student-response" };
const pick = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;
export function generateQuestions(count = 3, domain = "Advanced Math", difficulty = "Adaptive"): GeneratedQuestion[] {
  return generateQuestionSet(count,domain,difficulty);
}
type PublishedStudioTemplate={id:string;title:string;domain:string;status:string;min:number;max:number};
