function stagedHints(question:GeneratedQuestion){
  const skill=(question.skill||"").toLowerCase();
  if(skill.includes("function"))return["Find the input in the expression, then replace every x with that value.","Evaluate exponents first, then multiply, and finish with addition or subtraction."];
  if(skill.includes("radical")||question.prompt.includes("√"))return["Look for the number that produces the value under the radical when multiplied by itself.","A square root asks for the principal nonnegative value. Check your candidate by squaring it."];
  if(skill.includes("linear")||skill.includes("equation"))return["Undo operations in reverse order while keeping both sides balanced.","Collect variable terms on one side and constants on the other, then divide by the coefficient."];
  if(skill.includes("percent")||skill.includes("ratio"))return["Translate the relationship into a fraction or decimal before calculating.","Write percent as a number over 100, then identify the part, whole, or rate you need."];
  if(skill.includes("geometry")||skill.includes("circle")||skill.includes("triangle"))return["Sketch and label the quantities you know, then choose the formula connecting them.","Substitute the known values before simplifying; keep track of whether the question asks for length, area, or angle."];
  return["Identify what the question gives you and what it asks you to find.","Write one equation connecting those quantities, then simplify one operation at a time."];
}
function QuestionToolPanel({tool,onClose,scratchpad,onScratchpad}:{tool:"calculator"|"formulas"|"scratchpad";onClose:()=>void;scratchpad:string;onScratchpad:(value:string)=>void}){
  const [left,setLeft]=useState(""),[right,setRight]=useState(""),[operation,setOperation]=useState("+");
  const a=Number(left),b=Number(right),result=!left||!right?null:operation==="+"?a+b:operation==="−"?a-b:operation==="×"?a*b:b===0?null:a/b;
  return <aside className="question-tool-panel" aria-label={`${tool} panel`}><header><strong>{tool==="calculator"?"Calculator":tool==="formulas"?"SAT Math formulas":"Scratchpad"}</strong><button aria-label="Close tool" onClick={onClose}>×</button></header>{tool==="calculator"&&<div className="mini-calculator"><input inputMode="decimal" aria-label="First number" value={left} onChange={event=>setLeft(event.target.value)}/><select aria-label="Operation" value={operation} onChange={event=>setOperation(event.target.value)}>{["+","−","×","÷"].map(item=><option key={item}>{item}</option>)}</select><input inputMode="decimal" aria-label="Second number" value={right} onChange={event=>setRight(event.target.value)}/><output>{result===null?"—":Number.isInteger(result)?result:result.toFixed(4).replace(/0+$/,"")}</output></div>}{tool==="formulas"&&<div className="formula-reference"><article><b>Circle</b><span>A = πr²</span><span>C = 2πr</span></article><article><b>Rectangle</b><span>A = lw</span></article><article><b>Triangle</b><span>A = ½bh</span><span>a² + b² = c²</span></article><article><b>Prisms</b><span>V = lwh</span></article><article><b>Slope</b><span>m = (y₂ − y₁)/(x₂ − x₁)</span></article><article><b>Quadratic formula</b><span>x = (−b ± √(b² − 4ac))/2a</span></article></div>}{tool==="scratchpad"&&<textarea autoFocus value={scratchpad} onChange={event=>onScratchpad(event.target.value)} placeholder="Write notes, calculations, or a plan…"/>}</aside>;
}

function SegmentedControl<T extends string>({label,value,options,onChange}:{label:string;value:T;options:readonly {value:T;label:string}[];onChange:(value:T)=>void}){
  return <div className="segmented-control" role="group" aria-label={label}>{options.map(option=><button aria-pressed={value===option.value} className={value===option.value?"selected":""} key={option.value} onClick={()=>onChange(option.value)}>{option.label}</button>)}</div>;
}
function generateStudioQuestions(templates:PublishedStudioTemplate[]):GeneratedQuestion[]{return templates.flatMap((template,index)=>{const min=Number(template.min)||2,max=Math.max(min,Number(template.max)||9),coefficient=pick(min,max),solution=pick(2,12),constant=pick(1,15),result=coefficient*solution+constant;return[{id:`studio-${template.id}-${Date.now()}-${index}`,prompt:`Solve ${coefficient}x + ${constant} = ${result}.`,answers:[String(solution),String(solution+1),String(result-constant),String(Math.max(1,solution-1))],correct:0,explain:`Subtract ${constant}, then divide by ${coefficient}. x = ${solution}.`,domain:template.domain,skill:template.title,difficulty:"Studio published"}]})}

