  const submitSignin=()=>{const account=readLocalJson<{name:string;email:string}|null>("orbit-local-account",null);if(!account||account.email!==email.trim().toLowerCase()){setMessage("No local demo account matches that email. Create one or continue locally.");return}onContinue({name:account.name.split(/\s+/)[0],lastName:account.name.split(/\s+/).slice(1).join(" "),email:account.email,accountMode:"email"})};
