  const [started, setStarted] = useState(false); const [launching,setLaunching]=useState(false);const [launchLabel,setLaunchLabel]=useState("Preparing your study room"); const [index, setIndex] = useState(0); const [choice, setChoice] = useState<number|null>(null); const [submitted, setSubmitted] = useState(false); const [score, setScore] = useState(0); const [finished, setFinished] = useState(false); const [mistakes, setMistakes] = useState<MissedQuestion[]>([]); const [reviewMode,setReviewMode]=useState(false); const [resultReview,setResultReview]=useState(false); const [builder,setBuilder]=useState(false); const [questionCount,setQuestionCount]=useState(5); const [domain,setDomain]=useState("Advanced Math"); const [difficulty,setDifficulty]=useState("Adaptive"); const [timed,setTimed]=useState(false); const [secondsLeft,setSecondsLeft]=useState(0);const [timeExpired,setTimeExpired]=useState(false);const [sessionName,setSessionName]=useState("Advanced Math review"); const [hintUsed,setHintUsed]=useState(false);const [hintLevel,setHintLevel]=useState(0);const [confidence,setConfidence]=useState<AttemptSummary["confidence"]>("Okay");const [sessionAttempts,setSessionAttempts]=useState<AttemptSummary[]>([]);
  const [savedSession,setSavedSession]=useState<SavedPracticeSession|null>(()=>typeof window==="undefined"?null:readLocalJson<SavedPracticeSession|null>("orbit-active-practice",null));
  const [questionStartedAt,setQuestionStartedAt]=useState(()=>Date.now());
  const [eliminated,setEliminated]=useState<number[]>([]),[flagged,setFlagged]=useState<string[]>([]),[tool,setTool]=useState<"calculator"|"formulas"|"scratchpad"|null>(null),[toolsOpen,setToolsOpen]=useState(false),[scratchpad,setScratchpad]=useState("");
  const [response,setResponse]=useState("");
  const [reporting,setReporting]=useState(false),[reportSaved,setReportSaved]=useState(false);
  const dueReviews=dueReviewItems(missedItems);
  const reviewQueueCopy=dueReviews.length?`${dueReviews.length} question${dueReviews.length===1?" is":"s are"} ready now.`:missedItems.length?`${missedItems.length} question${missedItems.length===1?" is":"s are"} scheduled for a later review.`:"Complete practice to build your review queue.";
  const reportQuestion=(reason:string)=>{const reports=readLocalJson<unknown[]>("orbit-question-reports",[]);localStorage.setItem("orbit-question-reports",JSON.stringify([...reports,{questionId:questions[index]?.id,reason,reportedAt:new Date().toISOString()}]));setReporting(false);setReportSaved(true);window.setTimeout(()=>setReportSaved(false),1800)};
  useEffect(()=>{onBreakoutChange?.((started||launching)&&!finished);return()=>onBreakoutChange?.(false)},[started,launching,finished,onBreakoutChange]);
  useEffect(()=>{if(started&&!finished)window.scrollTo({top:0,behavior:"instant"})},[started,finished]);
  useEffect(()=>{if(!started||finished)return;const snapshot:SavedPracticeSession={questions,index,choice,response,submitted,score,mistakes,reviewMode,timed,secondsLeft,sessionName,hintUsed,hintLevel,confidence,sessionAttempts,flagged,eliminated,scratchpad,savedAt:new Date().toISOString()};localStorage.setItem("orbit-active-practice",JSON.stringify(snapshot));setSavedSession(snapshot)},[started,finished,questions,index,choice,response,submitted,score,mistakes,reviewMode,timed,secondsLeft,sessionName,hintUsed,hintLevel,confidence,sessionAttempts,flagged,eliminated,scratchpad]);
  useEffect(()=>{if(!started||finished||!timed||secondsLeft<=0)return;const timer=window.setInterval(()=>setSecondsLeft(value=>Math.max(0,value-1)),1000);return()=>clearInterval(timer)},[started,finished,timed,secondsLeft]);
  useEffect(()=>{if(!started||finished)return;const handle=(event:KeyboardEvent)=>{if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)return;if(["1","2","3","4"].includes(event.key)&&!submitted){const answer=Number(event.key)-1;if(!eliminated.includes(answer))setChoice(answer)}if(event.key.toLowerCase()==="f")setFlagged(items=>items.includes(questions[index].id)?items.filter(id=>id!==questions[index].id):[...items,questions[index].id]);if(event.key==="Enter"&&choice!==null)(submitted?next:submit)()};window.addEventListener("keydown",handle);return()=>window.removeEventListener("keydown",handle)},[started,finished,submitted,choice,index,questions,eliminated]);
  useEffect(()=>{if(!started||finished||!timed||secondsLeft!==0)return;const answeredIds=new Set(sessionAttempts.map(item=>item.questionId));const unanswered=questions.filter(question=>!answeredIds.has(question.id));const expiredMisses=unanswered.map(question=>({...question,missedAt:new Date().toISOString()}));const expiredAttempts=unanswered.map(question=>({domain:question.domain||"Advanced Math",skill:question.skill||"Mixed practice",correct:false,hintUsed:false,confidence:"Unsure" as const,questionId:question.id,prompt:question.prompt,templateId:question.templateId,templateVersion:question.templateVersion,seed:question.seed,difficulty:question.difficulty}));localStorage.removeItem("orbit-active-practice");setSavedSession(null);setMistakes(items=>[...items,...expiredMisses]);setSessionAttempts(items=>[...items,...expiredAttempts]);setTimeExpired(true);setFinished(true);onComplete(score,questions.length,[...mistakes,...expiredMisses],[],sessionName,[...sessionAttempts,...expiredAttempts])},[secondsLeft,started,finished,timed,questions,sessionAttempts,mistakes,onComplete,score,sessionName]);
