  if (!started) return <div className="product-page"><PageHeading eyebrow="PRACTICE" title="What do you want to sharpen?" copy="Start quickly or build a session around exactly what you need."/><div className="mode-grid">{savedSession&&<button className="resume-practice card" onClick={resumeSaved}><span>SESSION SAVED</span><h2>Continue {savedSession.sessionName}</h2><p>Question {savedSession.index+1} of {savedSession.questions.length}{savedSession.timed&&savedSession.secondsLeft!==undefined?` · ${Math.floor(savedSession.secondsLeft/60)}:${String(savedSession.secondsLeft%60).padStart(2,"0")} left`:""} · Saved {new Date(savedSession.savedAt).toLocaleDateString()}</p><strong>Resume session →</strong></button>}<button className="mode-feature card" onClick={startFresh}><span>ADAPTIVE RECOMMENDATION</span><h2>{recommendation?.skill||"Functions and factoring"}</h2><p>{recommendation?.reason||"A balanced starting point before Orbit has enough practice history."}</p><div className="adaptive-tags"><i>{recommendation?.domain||"Advanced Math"}</i><i>{recommendation?.difficulty||"Foundations"}</i></div><strong>Start 5-question workout <span>→</span></strong></button><button className={`mode-card card ${!dueReviews.length?"disabled":""}`} onClick={startReview} disabled={!dueReviews.length}><b>↻</b><h3>Missed questions</h3><p>{reviewQueueCopy}</p></button><button className="mode-card card" onClick={()=>begin(generateQuestions(5),"10-minute sprint",false,true)}><b>◷</b><h3>10-minute sprint</h3><p>Practice pacing under pressure.</p></button><button className="mode-card card" onClick={()=>setBuilder(true)}><b>＋</b><h3>Build a quiz</h3><p>Choose topics, difficulty, length, and pace.</p></button><button className="mode-card card" onClick={onSimulation}><b>▦</b><h3>SAT simulation</h3><p>Practice modules, timing, navigation, and review.</p></button>{published.length>0&&<button className="mode-card card studio-practice" onClick={()=>begin(generateStudioQuestions(published),"Studio published templates",false,false)}><b>◆</b><h3>Published studio set</h3><p>{published.length} reviewed local template{published.length===1?"":"s"} ready for practice.</p></button>}</div></div>;
  if (finished) return <div className="product-page result-wrap">{resultReview?<section className="card session-review"><header><div><span className="micro-label">SESSION REVIEW</span><h1>Understand every answer.</h1></div><button onClick={()=>setResultReview(false)}>← Summary</button></header>{sessionAttempts.map((attempt,i)=><article key={attempt.questionId||i} className={attempt.correct?"correct":"incorrect"}><span>{attempt.correct?"✓":"×"}</span><div><small>{attempt.domain} · {attempt.skill}{attempt.flagged?" · Flagged":""}</small><h2>{attempt.prompt}</h2><p><b>Your answer:</b> {attempt.selectedAnswer||"No answer"}</p><p><b>Correct answer:</b> {attempt.correctAnswer}</p><em>{attempt.explanation}</em></div></article>)}<button className="primary" onClick={startFresh}>Start fresh practice →</button></section>:<section className="card result-card"><div className="result-ring">{score}/{questions.length}</div><span>{timeExpired?"TIME EXPIRED":reviewMode?"REVIEW COMPLETE":"SESSION COMPLETE"}</span><h1>{timeExpired?"Time is up—your work is saved.":score === questions.length ? "Perfect work." : score/questions.length >= .66 ? "Strong session." : "Good start—keep going."}</h1><p>{timeExpired?"Unanswered questions were counted as incorrect and added to your review queue.":reviewMode?`${questions.length} reviewed questions were checked. Correct answers will return after a longer interval; misses return sooner.`:"Your exact misses have been saved for a future retry."}</p><div className="result-stats"><div><b>{Math.round(score/questions.length*100)}%</b><span>Accuracy</span></div><div><b>{mistakes.length}</b><span>To revisit</span></div><div><b>{timed?`${Math.round((questions.length*120-secondsLeft)/Math.max(1,sessionAttempts.length))}s`:`+${score*8}`}</b><span>{timed?"Average pace":"Mastery XP"}</span></div></div>{timed&&<small className="pace-note">{secondsLeft>0?`${Math.floor(secondsLeft/60)}:${String(secondsLeft%60).padStart(2,"0")} remained on the session clock.`:"Use your review queue to revisit questions left unanswered at timeout."}</small>}<div className="result-actions"><button onClick={()=>setResultReview(true)}>Review every answer</button><button className="primary" onClick={startFresh}>New practice</button></div></section>}</div>;
  const q=questions[index];
  const studentResponse=q.responseType==="student-response",normalizedResponse=response.trim().replaceAll(",",""),answerCorrect=studentResponse?normalizedResponse===q.answers[q.correct].replaceAll(",",""):choice===q.correct,hasAnswer=studentResponse?Boolean(response.trim()):choice!==null;
